// NOTE: n8n webhook v2 wraps POST body in .body — never remove the raw.body unwrap below
const raw = $input.first().json;
const body = raw.body || raw;          // webhook v2 puts POST body here
const d = body.data || body;
if (!d.lactateData || !Array.isArray(d.lactateData) || d.lactateData.length < 3) {
  throw new Error('Zu wenig Laktat-Messpunkte (min. 3)');
}
return [{ json: {
  sessionId:         d.sessionId        || null,
  customerId:        d.customerId       || null,
  customerName:      d.customerName     || 'Athlet',
  unit:              d.unit             || 'watt',
  currentMethod:     d.currentMethod    || 'dmax',
  zoneModel:         d.zoneModel        || '5-zones',
  stepCount:         d.stepCount        || d.lactateData.length,
  testDevice:        d.testDevice       || 'bike',
  lactateData:       d.lactateData,
  smoothedCurve:     d.smoothedCurve    || null,
  smoothModel:       d.smoothModel      || null,
  currentThresholds: d.currentThresholds || { lt1: null, lt2: null },
  vt1:               d.vt1    || null,
  vt2:               d.vt2    || null,
  vo2max:            d.vo2max != null ? d.vo2max : null,
  timestamp:         d.timestamp        || new Date().toISOString()
}}];

// Read session context (smoothedCurve from dashboard, lactateData for fallback)
const ctx = $('Parse Context Fields').first().json;
const lactateData   = ctx.lactateData   || [];
const smoothedCurve = ctx.smoothedCurve || null;   // pre-fitted dashboard curve — use as-is
const all = $input.all();

function extractPower(val) {
  if (val == null) return null;
  if (typeof val === 'number' && val > 5) return val;
  if (typeof val === 'object') {
    const p = val.power ?? val.load ?? val.v;
    if (typeof p === 'number' && p > 5) return p;
  }
  return null;
}

function lactatFromCurve(power, curve) {
  if (!curve || curve.length < 2) return null;
  const sorted = [...curve].sort((a, b) => a.power - b.power);
  for (let i = 0; i < sorted.length - 1; i++) {
    const p0 = sorted[i].power, p1 = sorted[i+1].power;
    if (power >= p0 && power <= p1 && p1 > p0) {
      const t = (power - p0) / (p1 - p0);
      return Math.round((sorted[i].lactate + t * (sorted[i+1].lactate - sorted[i].lactate)) * 100) / 100;
    }
  }
  if (power <= sorted[0].power)              return sorted[0].lactate;
  if (power >= sorted[sorted.length-1].power) return sorted[sorted.length-1].lactate;
  return null;
}

function lactatFromRaw(power) {
  const sorted = [...lactateData].sort((a,b) => (a.power||0)-(b.power||0));
  for (let i = 0; i < sorted.length - 1; i++) {
    const p0 = sorted[i].power||0, p1 = sorted[i+1].power||0;
    if (power >= p0 && power <= p1 && p1 > p0) {
      const t = (power - p0) / (p1 - p0);
      return sorted[i].lactate + t * (sorted[i+1].lactate - sorted[i].lactate);
    }
  }
  return null;
}

function buildPoint(power) {
  if (power == null) return null;
  const lactate = lactatFromCurve(power, smoothedCurve) ?? lactatFromRaw(power) ?? 0;
  return { power: Math.round(power), lactate: Math.round(lactate * 100) / 100 };
}

let bestResult = null;
const methodsArray = [];
const agentErrors = [];

for (const item of all) {
  const out = item.json;

  if (out.error) {
    const errMsg = typeof out.error === 'string' ? out.error : (out.error.message || JSON.stringify(out.error));
    agentErrors.push(errMsg);
    continue;
  }

  let p = null;
  if (out.ai_lt1 !== undefined || out.ai_lt2 !== undefined) {
    p = out;
  } else {
    const rawText = (typeof out.output === 'string' ? out.output : '') || (typeof out.text === 'string' ? out.text : '');
    if (rawText) {
      const match = rawText.match(/\{[\s\S]*\}/);
      if (match) { try { p = JSON.parse(match[0]); } catch(e) {} }
    }
  }

  if (!p) continue;

  const lt1Power = extractPower(p.ai_lt1);
  const lt2Power = extractPower(p.ai_lt2);

  if ((lt1Power != null || lt2Power != null) && !bestResult) {
    bestResult = {
      lt1:        lt1Power != null ? buildPoint(lt1Power) : null,
      lt2:        lt2Power != null ? buildPoint(lt2Power) : null,
      confidence: p.confidence ?? 0.7,
      reasoning:  typeof p.reasoning === 'string' ? p.reasoning : ''
    };
  }

  if (p.other_methods && typeof p.other_methods === 'object') {
    for (const [methodKey, methodVal] of Object.entries(p.other_methods)) {
      if (!methodVal) continue;
      const mLt1 = extractPower(methodVal.lt1), mLt2 = extractPower(methodVal.lt2);
      if (mLt1 != null || mLt2 != null) {
        methodsArray.push({
          method:     methodKey.replace(/_\d{4}(_\d{4})?$/, '').replace(/_/g, '-'),
          lt1:        mLt1 != null ? buildPoint(mLt1) : null,
          lt2:        mLt2 != null ? buildPoint(mLt2) : null,
          confidence: methodVal.confidence ?? 0.5,
          reasoning:  methodVal.reasoning || ''
        });
      }
    }
  }
}

// Algorithmic fallback
if (!bestResult) {
  if (lactateData.length >= 3) {
    const sorted = [...lactateData].sort((a,b) => (a.power||0)-(b.power||0));
    const baseLactate = sorted[0].lactate;
    function findPowerAtLactate(target) {
      for (let i = 0; i < sorted.length - 1; i++) {
        const l0 = sorted[i].lactate, l1 = sorted[i+1].lactate;
        const p0 = sorted[i].power||0, p1 = sorted[i+1].power||0;
        if (l0 <= target && l1 >= target && l1 > l0) return Math.round(p0 + (target-l0)/(l1-l0)*(p1-p0));
      }
      return null;
    }
    const errorNote = agentErrors.length > 0 ? ' Fehler: ' + agentErrors.join('; ') : ' AI returned no JSON.';
    bestResult = {
      lt1:        buildPoint(findPowerAtLactate(baseLactate + 0.5)),
      lt2:        buildPoint(findPowerAtLactate(baseLactate + 1.5)),
      confidence: 0.3,
      reasoning:  'Algorithmic fallback (Dickhuth +0.5/+1.5): baseline=' + baseLactate + ' mmol/L.' + errorNote
    };
  } else {
    throw new Error('Kein valides AI-Ergebnis und zu wenig Daten fuer Fallback');
  }
}

return [{ json: {
  success:     true,
  lt1:         bestResult.lt1,
  lt2:         bestResult.lt2,
  vt1:         ctx.vt1    || null,
  vt2:         ctx.vt2    || null,
  vo2max:      ctx.vo2max != null ? ctx.vo2max : null,
  curve:       smoothedCurve,   // always use the pre-fitted dashboard curve
  method:      'ai',
  confidence:  bestResult.confidence,
  reasoning:   bestResult.reasoning,
  methods:     methodsArray.length > 0 ? methodsArray : null,
  agentErrors: agentErrors.length > 0 ? agentErrors : null
}}];

const item = $input.first()?.json || {};
// error can be a string (API error) or an object with .message
const err = item.error;
const msg = typeof err === "string" ? err
          : typeof err === "object" && err?.message ? err.message
          : "Unbekannter Workflow-Fehler";
return [{ json: { success: false, lt1: null, lt2: null, method: null, reasoning: null, message: msg } }];

const ctx = $input.first().json;
const NL = String.fromCharCode(10);
const lt1 = ctx.currentThresholds && ctx.currentThresholds.lt1 ? JSON.stringify(ctx.currentThresholds.lt1) : 'null';
const lt2 = ctx.currentThresholds && ctx.currentThresholds.lt2 ? JSON.stringify(ctx.currentThresholds.lt2) : 'null';

const parts = [
  'Lactate step test analysis. Unit: ' + (ctx.unit || 'watt') + ', Device: ' + (ctx.testDevice || 'bike'),
  'Stages: ' + (ctx.stepCount || 0) + ', Zone model: ' + (ctx.zoneModel || '5-zones'),
  '',
  'IMPORTANT: The curve below is already fitted by the dashboard. DO NOT refit or smooth it.',
  'Use it directly to detect LT1 and LT2.',
  '',
];

if (ctx.smoothedCurve && ctx.smoothedCurve.length > 0 && ctx.smoothModel) {
  const m = ctx.smoothModel;
  parts.push('Pre-fitted smoothed lactate curve (' + ctx.smoothedCurve.length + ' points):');
  parts.push(JSON.stringify(ctx.smoothedCurve));
  parts.push('');
  parts.push('Curve metadata: model=' + m.model + ', early_phase=' + m.early_phase + ', v_break=' + m.v_break);
  parts.push('Raw measurement points (reference only — do NOT use for curve fitting):');
  parts.push(JSON.stringify(ctx.lactateData || []));
} else {
  parts.push('WARNING: No pre-fitted curve available. Use raw data only.');
  parts.push(JSON.stringify(ctx.lactateData || []));
}

parts.push('');
parts.push('Currently set thresholds — LT1: ' + lt1 + ', LT2: ' + lt2);
parts.push('');
parts.push('Follow the OUTPUT RULE in your system message. Return only valid JSON starting with { and ending with }.');
parts.push('DO NOT return ai_curve or curve parameters.');

return [{ json: Object.assign({}, ctx, { chatInput: parts.join(NL) }) }];
